function geoMunisByDept(deptCode) {
  return GEO_MUNIS.filter(m => m.dept_code === deptCode);
}

function geoDept(code) {
  return GEO_DEPTS.find(d => d.code === code);
}

function geoPais(code) {
  return GEO_PAISES.find(p => p.code === code);
}

function geoMuni(muniCode) {
  return GEO_MUNIS.find(m => m.code === muniCode);
}
